import{_ as p,a0 as l,w as a,s as d,ao as n,I as o,x as s,a1 as i,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"GNOME 搜索功能的一些小技巧 | LCTT x X-CMD","titleTemplate":false,"description":"GNOME 搜索功能的一些小技巧 | LCTT (202112) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GNOME 搜索功能的一些小技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GNOME 搜索功能的一些小技巧 | LCTT (202112) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202112/20211216 Hide or Add Specific Folders From GNOME Search Results in Ubuntu and Other Linux Distributions","title":"GNOME 搜索功能的一些小技巧","tag":"202112","desc":""},"relativePath":"202112/20211216 Hide or Add Specific Folders From GNOME Search Results in Ubuntu and Other Linux Distributions.md","filePath":"[post].md"}'),m={name:"202112/20211216 Hide or Add Specific Folders From GNOME Search Results in Ubuntu and Other Linux Distributions.md"};function f(u,t,g,b,T,h){const e=l("Link");return a(),d("div",null,[t[33]||(t[33]=n('<h1 id="gnome-搜索功能的一些小技巧" tabindex="-1">GNOME 搜索功能的一些小技巧 <a class="header-anchor" href="#gnome-搜索功能的一些小技巧" aria-label="Permalink to “GNOME 搜索功能的一些小技巧”">​</a></h1><p>你可能已經注意到，當你在 GNOME 菜單/活動區搜索某樣東西時，它也會顯示名稱與搜索詞相匹配的文件，以及已安裝的應用。</p><p><img src="https://img.linux.net.cn/data/attachment/album/202112/25/115842tf8jjgn4ttz7nf4m.jpg" alt=""></p><p>這是個很方便的功能。如果你記得文件名，甚至是它的一部分，你可以很容易地搜索到它，只需按下 <code>Super</code> 鍵（<code>Windows</code> 鍵）並輸入文件名就可以打開它。</p><p>但是，圍繞這個搜索功能，有一些你可能不知道或從未關心過的小問題。</p><p>在這篇文章中，我將分享你如何控制 GNOME 搜索功能，從搜索選項中添加或隱藏文件夾，以及完全禁用它。</p>',6)),o("p",null,[t[1]||(t[1]=s("注意：這專門針對使用 GNOME 的發行版。請 ",-1)),i(e,{href:"https://itsfoss.com/find-desktop-environment/"},{default:r(()=>[...t[0]||(t[0]=[s("確認你使用的是哪種桌面環境",-1)])]),_:1}),t[2]||(t[2]=s("，確保是 GNOME。",-1))]),t[34]||(t[34]=o("h3",{id:"文件搜索的默認位置",tabindex:"-1"},[s("文件搜索的默認位置 "),o("a",{class:"header-anchor",href:"#文件搜索的默認位置","aria-label":"Permalink to “文件搜索的默認位置”"},"​")],-1)),o("p",null,[t[4]||(t[4]=s("GNOME 的搜索功能使用了一個叫做 ",-1)),i(e,{href:"https://wiki.gnome.org/Projects/Tracker/Documentation/GettingStarted"},{default:r(()=>[...t[3]||(t[3]=[s("Tracker Miner FS",-1)])]),_:1}),t[5]||(t[5]=s(" 的工具。請不要被 “tracker” 和 “miner” 這樣的術語嚇到。它不是在監視你，也不是在你的系統上挖掘加密貨幣。它的基本功能是作為一個搜索引擎和資料庫，為你提供即時搜索結果。",-1))]),t[35]||(t[35]=n('<p>默認情況下，文件索引發生在元文件夾，如文檔、音樂、圖片和視頻目錄及其子目錄。主頁和下載文件夾中的文件也會被索引，但不包括其子目錄中的文件。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/gnome-default-search-location.png?resize=800%2C533&amp;ssl=1" alt="Default locations for file search"></p><p>如果你在你的主文件夾中創建了一些新的目錄，這些文件將不會被索引。</p><p>然而，最近訪問的文件也會被自動編入索引。如果你最近打開了一個文件，它將被添加到 “最近的文件” 中，並將出現在搜索結果中，而不管它在什麼地方。</p><p>如果你還不知道的話，你可以在文件管理器中看到你最近訪問的文件：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/access-recent-files-gnome-linux.png?resize=735%2C414&amp;ssl=1" alt="Accessing recent files in GNOME file manager"></p><h3 id="在搜索結果中添加一個文件夾的內容" tabindex="-1">在搜索結果中添加一個文件夾的內容 <a class="header-anchor" href="#在搜索結果中添加一個文件夾的內容" aria-label="Permalink to “在搜索結果中添加一個文件夾的內容”">​</a></h3><p>假設你在你的主目錄中為編碼項目創建了一個文件夾。這些文件不會被索引，也不會出現在搜索結果中（除非你通過雙擊打開了一個文件，並且它被添加到最近的文件中）。</p><p>要在搜索結果中添加自定義文件夾中的文件，你可以將該文件夾添加到搜索位置。</p><p>通過在菜單/活動區搜索打開 “設置” 應用。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/04/settings-search-ubuntu-20-04.jpg?resize=800%2C230&amp;ssl=1" alt="Search for settings application"></p><p>從左側邊欄進入 “搜索” 選項，點擊頂部的“搜索位置”選項。在彈出的窗口中，進入 “其他” 標籤，點擊 “+” 符號。它將打開文件瀏覽器，你可以添加你想要的文件夾。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/gnome-add-search-location.png?resize=800%2C525&amp;ssl=1" alt="Adding a custom folder content to search"></p><p>如果你在剛剛添加的文件夾中搜索一個文件名進行測試，你現在應該在搜索結果中看到它。它應該是即時的，但如果不是，請嘗試註銷或重啓系統。</p><h3 id="從搜索結果中隱藏一個文件夾" tabindex="-1">從搜索結果中隱藏一個文件夾 <a class="header-anchor" href="#從搜索結果中隱藏一個文件夾" aria-label="Permalink to “從搜索結果中隱藏一個文件夾”">​</a></h3><p>如果你不希望某個特定文件夾的文件出現在搜索結果中，你可以隱藏它。</p><p>如果你不希望在搜索中出現圖片、文檔、視頻等元文件夾的內容，你可以從搜索位置設置中禁用它。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/disable-folders-from-search.png?resize=800%2C533&amp;ssl=1" alt="Disable meta folders from the search"></p><p>如果你只想讓文檔下的某個文件夾的內容不出現在搜索結果中，你只需要在該文件夾中創建一個名為 <code>.nomedia</code> 的新文件。你也可以將該文件命名為 <code>.git</code>、<code>.trackerignore</code> 或 <code>.hg</code>。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/hide-specific-folder-from-search-results.png?resize=751%2C382&amp;ssl=1" alt="Hide specific folder from search results by creating file named .nomedia or .hg or .git"></p>',20)),o("p",null,[t[8]||(t[8]=s("如果你在鼠標右鍵中沒有看到創建新文件的選項，你必須做一些調整來增加 ",-1)),i(e,{href:"https://itsfoss.com/add-new-document-option/"},{default:r(()=>[...t[6]||(t[6]=[s("在右鍵上下文菜單中創建新文件選項",-1)])]),_:1}),t[9]||(t[9]=s("。還要注意的是，任何名稱中以 ",-1)),t[10]||(t[10]=o("code",null,".",-1)),t[11]||(t[11]=s(" 開頭的文件都會被隱藏起來，不能被正常查看。要 ",-1)),i(e,{href:"https://itsfoss.com/hide-folders-and-show-hidden-files-in-ubuntu-beginner-trick/"},{default:r(()=>[...t[7]||(t[7]=[s("切換顯示隱藏文件",-1)])]),_:1}),t[12]||(t[12]=s("，按 ",-1)),t[13]||(t[13]=o("code",null,"Ctrl+H",-1)),t[14]||(t[14]=s(" 鍵。",-1))]),t[36]||(t[36]=n('<p>這種隱藏可能不會立即生效，因為該文件可能已經被索引了。你可能必須註銷或重啓才能看到效果。</p><p>如果你手動訪問一個文件，它將被添加到最近的文件中，並且會出現在搜索結果中，儘管文件夾中的文件被忽略了。</p><p>你可以從 “設置 -&gt; 隱私 -&gt; 文件歷史 &amp; 垃圾箱” 刪除最近的文件歷史或完全禁用它（如果你想的話）。不過我認為沒有必要，所以在這裏你自己決定吧。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/clear-or-disable-file-history-gnome-linux.png?resize=800%2C389&amp;ssl=1" alt="Clear or disable file access history in GNOME"></p><h3 id="禁用所有文件的搜索結果" tabindex="-1">禁用所有文件的搜索結果 <a class="header-anchor" href="#禁用所有文件的搜索結果" aria-label="Permalink to “禁用所有文件的搜索結果”">​</a></h3><p>如果你不希望任何文件出現在搜索結果中，你可以在搜索設置中完全禁用對文件的搜索。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/disable-search-for-files-gnome.png?resize=800%2C475&amp;ssl=1" alt="Disable search results for all files"></p><p>你應該通過點擊頂部的搜索切換按鈕完全禁用搜索功能，它可能會干擾 GNOME 桌面環境的正常功能。</p><p>關於它的更多細節可以在 [項目主頁] 中找到。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>這裏的 <em>討論的是文件搜索</em>。GNOME 桌面也可以在日曆、字符映射和其他一些程序中進行搜索。你可以禁用或啓用可用的搜索選項，但我們這篇不針對這些。</p>',11)),o("p",null,[t[16]||(t[16]=s("我希望你覺得這個快速提示對 ",-1)),i(e,{href:"https://itsfoss.com/gnome-tricks-ubuntu/"},{default:r(()=>[...t[15]||(t[15]=[s("定製你的 GNOME 體驗",-1)])]),_:1}),t[17]||(t[17]=s(" 有幫助。如果你知道其他一些你想讓別人知道的技巧，請在評論中與我們分享。",-1))]),t[37]||(t[37]=o("hr",null,null,-1)),o("p",null,[t[19]||(t[19]=s("via: ",-1)),i(e,{href:"https://itsfoss.com/control-gnome-file-search/"},{default:r(()=>[...t[18]||(t[18]=[s("https://itsfoss.com/control-gnome-file-search/",-1)])]),_:1})]),o("p",null,[t[24]||(t[24]=s("作者：",-1)),i(e,{href:"https://itsfoss.com/author/abhishek/"},{default:r(()=>[...t[20]||(t[20]=[s("Abhishek Prakash",-1)])]),_:1}),t[25]||(t[25]=s(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[21]||(t[21]=[s("lujun9972",-1)])]),_:1}),t[26]||(t[26]=s(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:r(()=>[...t[22]||(t[22]=[s("geekpi",-1)])]),_:1}),t[27]||(t[27]=s(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[23]||(t[23]=[s("wxy",-1)])]),_:1})]),o("p",null,[t[30]||(t[30]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[28]||(t[28]=[s("LCTT",-1)])]),_:1}),t[31]||(t[31]=s(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:r(()=>[...t[29]||(t[29]=[s("Linux中國",-1)])]),_:1}),t[32]||(t[32]=s(" 榮譽推出",-1))])])}const M=p(m,[["render",f]]);export{x as __pageData,M as default};
